SELECT CASE WHEN sqft >= 14830 THEN 'high' WHEN sqft >= 4746 THEN 'mid' ELSE 'low' END sqft_bucket, ROUND((100 * SUM(CASE WHEN region = 'South' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_south, ROUND((100 * SUM(CASE WHEN city = 'Bangkok' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_bangkok FROM stores WHERE store_name LIKE '%Tow%' OR sqft BETWEEN 11660 AND 13039 GROUP BY 1 ORDER BY sqft_bucket DESC
